  const list=value=>value.split('|').map(item=>item.trim()).filter(Boolean);
  const matrix=(name,category,start,count,topics,frames,adult=false)=>{
    const made=[];
    for(let frameIndex=0;frameIndex<frames.length&&made.length<count;frameIndex++){
      for(const topic of topics){if(made.length===count)break;made.push(frames[frameIndex].replace('{}',topic));}
    }
    if(made.length!==count)throw new Error(`Incomplete pack ${name}: ${made.length}/${count}`);
    addBatch(name,category,start,made,adult);
  };

